-- ── brand_styles ────────────────────────────────────────────────────────────
-- Every fingerprint has ONE job: separate the style from the sibling it is
-- actually confused with. In this pack that sibling is nearly always a
-- NEAR-IDENTICAL SHOE FROM THE SAME BRAND (Suede vs Clyde, Classic Leather vs
-- Club C, Clifton vs Bondi) or the SAME SWEATSHIRT IN A CHEAPER FABRIC (Reverse
-- Weave vs Powerblend) — which is the pack's real problem, because these pairs
-- photograph the same and comp differently.
--
-- The designed-vs-damage warnings live HERE rather than in the tells, because
-- brandPackPromptBlock renders fingerprints VERBATIM while the grading block
-- truncates tells at 900 chars (the US-1740 rule).
insert into public.brand_styles
  (brand_key, style_name, aliases, department, category, product_line, visual_fingerprint, fabric_tech, era, msrp_band, keywords, source_url, confidence, verified, updated_by) values

  -- CHAMPION: the Reverse Weave / Powerblend pair is the money disambiguation in
  -- this entire pack — same silhouette, same sleeve C, multiples apart in price.
  ('champion', 'Reverse Weave Hoodie', ARRAY['reverse weave hoodie','reverse weave hooded','rw hoodie','reverse weave pullover']::text[], 'Unisex', 'sweatshirt', 'Reverse Weave',
   'Champion''s flagship and the highest-value ordinary garment in this pack. THE READ IS THE SIDE GUSSET, NOT THE LOGO: Reverse Weave is a 1938 CONSTRUCTION in which the fabric grain runs HORIZONTALLY (which is what resists vertical shrinkage and what the name means), with a ribbed EXPANSION PANEL running vertically down each side seam. That side panel is visible in a plain photo and it is the whole identification. vs the Powerblend hoodie: SAME silhouette, SAME sleeve C logo, SAME colours, NO side gusset, and a fraction of the price — so a model that reads the sleeve C and stops has not identified anything. Do not read the side panel as a repair, an inserted seam or a manufacturing defect: it is the feature the buyer is paying for. Then read the NECK TAG, because on Champion the era is most of the remaining value.',
   ARRAY['reverse weave','cotton fleece']::text[], '1938-present', '$60-$90 (modern retail; vintage comps far higher)', ARRAY['reverse weave','hoodie','side gusset','champion','vintage']::text[],
   'https://www.champion.com/', 0.70, false, 'migration:00465'),
  ('champion', 'Reverse Weave Crewneck', ARRAY['reverse weave crewneck','reverse weave crew','rw crewneck']::text[], 'Unisex', 'sweatshirt', 'Reverse Weave',
   'The crewneck half of the Reverse Weave line and the original form of the construction. Identified exactly as the hoodie is — the ribbed side EXPANSION GUSSET down each side seam plus the horizontal grain — and it carries the same warning: the gusset is the feature, not a repair. vs the Reverse Weave hoodie: only the hood differs, and the crewneck is the more commonly faked of the two in vintage colourways. The neck tag dates it and the date is most of the price.',
   ARRAY['reverse weave','cotton fleece']::text[], '1938-present', '$55-$85 (modern retail; vintage comps far higher)', ARRAY['reverse weave','crewneck','side gusset','champion','vintage']::text[],
   'https://www.champion.com/', 0.70, false, 'migration:00465'),
  ('champion', 'Powerblend Hoodie', ARRAY['powerblend','powerblend hoodie','power blend','eco fleece','champion eco']::text[], 'Unisex', 'sweatshirt', 'Powerblend / Eco',
   'THE DECOY, and it is recorded for exactly that reason. Powerblend (and the Eco fleece line) is Champion''s ORDINARY cotton-poly sweatshirt: same silhouette as the Reverse Weave, same sleeve C logo, same colour range, sold at a fraction of the price — and it is what most Champion hoodies actually are. THE SEPARATOR IS THE SIDE SEAM: a Powerblend has a plain side seam and NO ribbed expansion gusset, and its tag says Powerblend or Eco rather than Reverse Weave. Calling a Powerblend a Reverse Weave overprices it by a multiple and the photo will not contradict you, because the two garments look the same from the front. Check the side seam and the tag before ever using the words reverse weave.',
   ARRAY['cotton blend','fleece']::text[], 'modern', '$30-$45', ARRAY['powerblend','eco','hoodie','champion','not reverse weave']::text[],
   'https://www.champion.com/', 0.65, false, 'migration:00465'),
  ('champion', 'Script Logo Tee', ARRAY['script logo tee','champion script','script tee','champion script tee']::text[], 'Unisex', 'top', 'Script',
   'The cursive Champion SCRIPT wordmark across the chest — the brand''s other signature graphic, distinct from the sleeve C. Recorded because the script is what a buyer searches on a tee, and because the tee is where the ordinary-word hazard bites hardest: a chest graphic reading Champion is the brand, but a chest graphic reading 1996 NBA Champion is a team tee from an entirely different maker. Read the NECK tag, not the chest print, to settle the brand.',
   ARRAY['cotton']::text[], 'long-running', '$25-$35', ARRAY['script','logo tee','champion','chest graphic']::text[],
   'https://www.champion.com/', 0.60, false, 'migration:00465'),

  -- FILA: the Disruptor's sole is designed. The vintage line is the value.
  ('fila', 'Disruptor II', ARRAY['disruptor','disruptor 2','disruptor ii','fila disruptor']::text[], 'Unisex', 'footwear', 'Disruptor',
   'Fila''s highest-volume resale shoe and the original chunky dad shoe. THE SOLE IS DESIGNED, NOT DEFORMED: the outsole is a deliberately oversized, exaggerated sawtooth platform — it is the entire point of the shoe, and a brand-new pair looks bulbous and misshapen to a naive grader. Do not read the volume of the sole as swelling, delamination or heat damage. The REAL Disruptor condition axes, all of which DO count: YELLOWING of the white midsole (the single biggest value lever on this shoe, and it is progressive and irreversible), sole/upper separation at the toe, and creasing across the toe box. NOTE THE DATE TRAP: the silhouette is a 1996 design but the shoe in hand is nearly always the 2017+ reissue — the retro shape is not evidence of age.',
   ARRAY['leather','synthetic']::text[], '2017-present reissue (1996 original)', '$65-$85', ARRAY['disruptor','chunky','dad shoe','platform','fila']::text[],
   'https://www.fila.com/', 0.65, false, 'migration:00465'),
  ('fila', 'Vintage Track Jacket', ARRAY['fila vintage','settanta','terrinda','fila track jacket','fila velour']::text[], 'Unisex', 'jacket', 'Fila Vintage',
   'The Italian-era sportswear line (the Settanta and Terrinda families) and the collectible half of the brand — the tennis heritage the Bjorn Borg association sits on. The read is the F-BOX logo on the chest plus the red/navy stripe blocking at the collar and cuffs. vs the modern Fila Sport track jacket: the vintage line is Italian-made and the tag says so, which is the separator and is worth checking, because the two silhouettes are close and the values are not.',
   ARRAY['polyester','velour','nylon']::text[], '1970s-1990s (Italian era)', 'varies (vintage)', ARRAY['fila vintage','settanta','terrinda','track jacket','italy']::text[],
   'https://www.fila.com/', 0.55, false, 'migration:00465'),
  ('fila', 'F-Box Logo Tee', ARRAY['f-box','fbox','fila box logo','fila logo tee']::text[], 'Unisex', 'top', 'F-Box',
   'The block F-box logo across the chest — Fila''s core graphic and the brand read on an unlabelled photo, since the logo is embroidered or printed rather than tagged. The red/white/navy block is the brand''s own; a monochrome F is usually a modern line. Recorded as the volume apparel item beside the Disruptor.',
   ARRAY['cotton']::text[], 'long-running', '$25-$40', ARRAY['f-box','logo tee','fila','chest graphic']::text[],
   'https://www.fila.com/', 0.55, false, 'migration:00465'),
  ('fila', 'Grant Hill', ARRAY['grant hill','grant hill 96','fila grant hill','gh2']::text[], 'Men', 'footwear', 'Grant Hill',
   'The 1990s basketball signature line and the collectible half of Fila''s footwear. Recorded as the Disruptor''s opposite pole: same brand, entirely different buyer, and the value sits in the original 1990s pairs and the retros rather than in the volume line. Read the model name off the tongue; do not call a chunky white Fila a Grant Hill.',
   ARRAY['leather']::text[], '1990s original / retros', 'varies', ARRAY['grant hill','basketball','fila','signature']::text[],
   'https://www.fila.com/', 0.55, false, 'migration:00465'),

  -- PUMA: the Suede/Clyde pair is the trap. The Formstrip is the read.
  ('puma', 'Suede Classic', ARRAY['suede','suede classic','puma suede','suede xl']::text[], 'Unisex', 'footwear', 'Suede',
   'PUMA''s highest-volume resale shoe and one of the longest-running silhouettes in sport: a low-top suede upper with the FORMSTRIP sweeping from the midsole to the laces and a gum or rubber cupsole. THE READ IS THE FORMSTRIP, which is stitched in and survives a cut tag. vs THE CLYDE — and this is the trap: the Clyde is the SAME shoe with Walt Frazier''s endorsement, a different tongue/branding treatment and frequently a materially different value. They photograph almost identically. Read the tongue label and the model name; never call a Suede a Clyde just because it is a suede PUMA. Condition: the suede nap is the grade — scuffing, matting and water staining on suede are progressive and irreversible, and a clean-looking photo taken straight-on hides all three.',
   ARRAY['suede','rubber cupsole']::text[], '1968-present', '$70-$90', ARRAY['suede','suede classic','formstrip','puma']::text[],
   'https://www.puma.com/', 0.65, false, 'migration:00465'),
  ('puma', 'Clyde', ARRAY['clyde','puma clyde','clyde og','walt frazier']::text[], 'Unisex', 'footwear', 'Clyde',
   'THE SUEDE''S TWIN AND THE PACK''S CLOSEST CONFUSION PAIR. The Clyde is the Suede built for Walt "Clyde" Frazier — the same last and the same silhouette, separated by the tongue branding and the model name on the label, and on many releases worth materially more. Nothing in a straight-on photo reliably separates them, so the tag settles it. Recorded precisely because a model that guesses here will be plausibly and confidently wrong half the time.',
   ARRAY['suede','rubber cupsole']::text[], '1973-present', '$80-$110', ARRAY['clyde','walt frazier','formstrip','puma','suede']::text[],
   'https://www.puma.com/', 0.60, false, 'migration:00465'),
  ('puma', 'Speedcat', ARRAY['speedcat','speedcat og','puma speedcat']::text[], 'Unisex', 'footwear', 'Speedcat',
   'The low-profile motorsport-derived silhouette — the flattest, most slipper-like shoe in the PUMA line and the visual opposite of the Suede''s cupsole. Genuinely distinguishable in a photo for once: the sole is thin and the profile hugs the foot. Recorded because it is a current high-demand model whose silhouette a model might mistake for a generic flat trainer.',
   ARRAY['suede','leather']::text[], '1999-present', '$100-$120', ARRAY['speedcat','motorsport','low profile','formstrip','puma']::text[],
   'https://www.puma.com/', 0.55, false, 'migration:00465'),
  ('puma', 'T7 Track Jacket', ARRAY['t7','t7 track jacket','puma track jacket','iconic t7']::text[], 'Unisex', 'jacket', 'T7',
   'PUMA''s signature apparel piece and the reason this brand needs two sizing charts: the T7 is a GARMENT sized by an alpha letter while everything above is a shoe sized by a stamped number, under the same brand name. The read is the taped FORMSTRIP running down each sleeve — the shoe''s mark applied to a garment. Recorded as the apparel anchor of a brand most models will assume is footwear-only.',
   ARRAY['polyester','tricot']::text[], 'long-running', '$65-$85', ARRAY['t7','track jacket','formstrip','puma','apparel']::text[],
   'https://www.puma.com/', 0.55, false, 'migration:00465'),

  -- REEBOK: the Classic Leather / Club C pair, and the Pump's invisible defect.
  ('reebok', 'Classic Leather', ARRAY['classic leather','reebok classic','cl leather','classics']::text[], 'Unisex', 'footwear', 'Classic',
   'Reebok''s highest-volume resale shoe: a plain white/neutral leather low-top RUNNING shoe with a Vector on the side. vs THE CLUB C — the pack''s other near-identical pair and a genuinely hard one: both are plain white leather low-tops with a Vector and they photograph the same. THE SEPARATOR IS THE MIDSOLE PROFILE: the Classic Leather is a running shoe, so its midsole is TALLER and more built-up with a visible foam wedge lifting the heel; the Club C is a tennis shoe on a slim, flat cupsole. If the tongue label is not legible, say which family it appears to be and flag the uncertainty rather than picking. Condition: the white midsole YELLOWS, which is progressive, irreversible and a real value lever.',
   ARRAY['leather']::text[], '1983-present', '$75-$90', ARRAY['classic leather','vector','white leather','reebok']::text[],
   'https://www.reebok.com/', 0.65, false, 'migration:00465'),
  ('reebok', 'Club C 85', ARRAY['club c','club c 85','clubc','club champion']::text[], 'Unisex', 'footwear', 'Club C',
   'THE CLASSIC LEATHER''S TWIN. The Club C (Club Champion) is a TENNIS shoe: a slim, flat cupsole and a tennis-derived last, where the Classic Leather is a running shoe on a taller foam midsole. Same white leather, same Vector, and they comp differently. The midsole height is the read and the tongue label settles it. Recorded as the deliberate counterpart to the Classic Leather so the pair is disambiguated from both sides rather than one.',
   ARRAY['leather']::text[], '1985-present', '$75-$90', ARRAY['club c','club champion','vector','tennis','reebok']::text[],
   'https://www.reebok.com/', 0.65, false, 'migration:00465'),
  ('reebok', 'Instapump Fury', ARRAY['instapump','instapump fury','pump fury','fury']::text[], 'Unisex', 'footwear', 'Pump',
   'THE LACELESS ONE — and the shoe whose defining feature is invisible in a photo. The Instapump Fury has NO LACES AT ALL by design (the fit comes entirely from the inflatable bladder), so a photo showing a laceless shoe is showing the product, not a shoe missing its laces. THE PUMP IS A MECHANISM AND IT MUST BE TESTED: press the tongue button and the collar should firm; the release valve should let it down. A dead pump is a FUNCTIONAL defect that materially changes the value and that no photo of a clean upper will ever reveal — test it in hand and state the result. Never grade a Pump on its upper alone.',
   ARRAY['synthetic','pump bladder']::text[], '1994-present', '$160-$190', ARRAY['instapump','fury','pump','laceless','reebok']::text[],
   'https://www.reebok.com/', 0.65, false, 'migration:00465'),
  ('reebok', 'Freestyle Hi', ARRAY['freestyle','freestyle hi','5411','reebok freestyle']::text[], 'Women', 'footwear', 'Freestyle',
   'The 1982 aerobics high-top — the shoe that built the company and still a steady women''s seller. The read is the double ankle strap and the soft garment-leather upper, which is genuinely distinguishable from the brand''s other white leather shoes. Recorded because it is the one Reebok silhouette a model will not confuse with the Classic Leather / Club C pair, and saying so is useful.',
   ARRAY['garment leather']::text[], '1982-present', '$75-$85', ARRAY['freestyle','aerobics','high top','reebok','vector']::text[],
   'https://www.reebok.com/', 0.55, false, 'migration:00465'),
  ('reebok', 'Nano', ARRAY['nano','reebok nano','crossfit nano','nano x']::text[], 'Unisex', 'footwear', 'Nano',
   'The training/CrossFit shoe and the brand''s modern performance anchor — a flat, wide, stable platform, the opposite of a cushioned runner. Recorded as the current-era counterpart to the classics: a Nano is a MODERN shoe (numbered by generation, Nano X1 through the current run), so unlike the Vector-marked classics its model number dates it. Read the generation number off the shoe and carry it into the title — buyers shop the generation.',
   ARRAY['synthetic','flexweave']::text[], '2012-present', '$130-$150', ARRAY['nano','crossfit','training','reebok','generation']::text[],
   'https://www.reebok.com/', 0.55, false, 'migration:00465'),

  -- ASICS: the split tongue is the one thing readable with no tag.
  ('asics', 'GEL-Kayano', ARRAY['gel-kayano','gel kayano','kayano','asics kayano']::text[], 'Unisex', 'footwear', 'GEL-Kayano',
   'ASICS''s flagship stability RUNNING shoe and its highest-volume resale model — a heavily built, supportive trainer, generationally numbered (Kayano 25, 30, and so on). Read the GENERATION NUMBER off the shoe and title it: buyers shop the generation and the numbers span a decade of very different shoes. vs the GEL-Nimbus (the neutral cushioned flagship): the two are the brand''s two premium trainers and are close in profile — the Kayano is the STABILITY shoe and carries a firmer medial post; the Nimbus does not. If the model name is not legible the article number on the tongue settles it, which is what the decoder is for. Condition: the foam midsole compresses and the shoe is dead before the upper looks it.',
   ARRAY['GEL','foam midsole']::text[], '1993-present', '$160-$180', ARRAY['gel-kayano','kayano','stability','running','asics']::text[],
   'https://www.asics.com/', 0.65, false, 'migration:00465'),
  ('asics', 'GEL-Lyte III', ARRAY['gel-lyte iii','gel lyte 3','gel-lyte 3','glc3','gel lyte iii']::text[], 'Unisex', 'footwear', 'GEL-Lyte',
   'THE ONE ASICS IDENTIFIABLE WITH NO TAG AT ALL, and the brand''s lifestyle/collector anchor. The GEL-Lyte III has a SPLIT TONGUE — the tongue is divided into two separate halves down the middle, which no other mainstream sneaker does. It is plainly visible in any photo of the shoe from above and it is a construction, so it survives a cut tag and a missing box. This is ASICS''s counterpart to the G-Star 3D knee. vs the GEL-Lyte V and the Gel-Saga: same family, ordinary single tongue.',
   ARRAY['GEL','suede','mesh']::text[], '1990-present', '$110-$130', ARRAY['gel-lyte iii','split tongue','sportstyle','asics','collector']::text[],
   'https://www.asics.com/', 0.70, false, 'migration:00465'),
  ('asics', 'GEL-Nimbus', ARRAY['gel-nimbus','gel nimbus','nimbus','asics nimbus']::text[], 'Unisex', 'footwear', 'GEL-Nimbus',
   'The neutral cushioned flagship and the Kayano''s closest sibling — the two are ASICS''s premium trainers and sit at the same price. THE SEPARATOR IS SUPPORT, NOT SHAPE: the Kayano is a stability shoe with a firmer medial post, the Nimbus is neutral. That is difficult to see in a photo, so read the model name or the tongue article number rather than judging the profile. Also generationally numbered — read the number and title it.',
   ARRAY['GEL','foam midsole']::text[], '1999-present', '$160-$180', ARRAY['gel-nimbus','nimbus','neutral','cushioned','running','asics']::text[],
   'https://www.asics.com/', 0.60, false, 'migration:00465'),
  ('asics', 'GEL-1130', ARRAY['gel-1130','gel 1130','1130','asics 1130']::text[], 'Unisex', 'footwear', 'GEL-1000 series',
   'The retro-runner that carried ASICS''s late-2010s/2020s lifestyle revival — a silver/white mesh-and-synthetic trainer worn as a fashion shoe rather than a running one. Recorded because its BARE FOUR-DIGIT NAME is exactly the trap this brand''s decoder is drawn to avoid: 1130 is a model number, not a code, and it must be corroborated by an ASICS tag or the side stripes. A tag reading only 1130 recovers nothing on its own — that is the Lee 101 rule, and it is why only the 8-character article number is decoded.',
   ARRAY['mesh','synthetic','GEL']::text[], '2022-present revival', '$100-$120', ARRAY['gel-1130','1130','retro runner','sportstyle','asics']::text[],
   'https://www.asics.com/', 0.55, false, 'migration:00465'),

  -- ON RUNNING: the holes are the product. This is the pack's MOTHER-fray entry.
  ('onrunning', 'Cloud 5', ARRAY['cloud 5','cloud5','on cloud 5','the cloud','cloud']::text[], 'Unisex', 'footwear', 'Cloud',
   'On''s highest-volume resale shoe and the brand''s core silhouette. THE HOLES IN THE SOLE ARE THE PRODUCT — this is the most expensive error available on this brand. The CloudTec outsole is built from hollow rubber pods, so the shoe HAS LARGE OPEN VOIDS RIGHT THROUGH IT BY DESIGN and a brand-new pair looks worn through to daylight. Grading them as damage marks a mint shoe down to Poor. The designed voids are uniform, clean-edged, deliberately shaped and IDENTICAL ON BOTH SHOES. The real defects, which DO count: a pod that has COLLAPSED, TORN or split at its root, and the brand''s own well-known nuisance — STONES AND DEBRIS wedged inside the pods, which is cleanable and should be noted rather than graded as structural damage. Note the speed-lace system: the elastic laces are the product, not a replacement.',
   ARRAY['CloudTec','Speedboard']::text[], '2010-present', '$140-$160', ARRAY['cloud 5','cloudtec','on running','speedboard','holes are designed']::text[],
   'https://www.on-running.com/', 0.70, false, 'migration:00465'),
  ('onrunning', 'Cloudmonster', ARRAY['cloudmonster','cloud monster','monster','on cloudmonster']::text[], 'Unisex', 'footwear', 'Cloud',
   'The max-cushion model — the largest CloudTec pods in the line, so the designed voids are BIGGER and the mistake-a-new-shoe-for-a-destroyed-one hazard is at its worst here. Same rule as the Cloud 5: the holes are the product; a collapsed or torn pod is the defect. vs the Cloud 5: the Cloudmonster''s stack is visibly much taller. Because the foam is the product on a max-cushion shoe, the MIDSOLE is the grade — a compressed one is a total loss even under a spotless upper, exactly as on HOKA in this same pack.',
   ARRAY['CloudTec','Speedboard','Helion foam']::text[], '2022-present', '$170-$190', ARRAY['cloudmonster','max cushion','cloudtec','on running']::text[],
   'https://www.on-running.com/', 0.65, false, 'migration:00465'),
  ('onrunning', 'Cloudnova', ARRAY['cloudnova','cloud nova','nova','on cloudnova']::text[], 'Unisex', 'footwear', 'Cloud',
   'The lifestyle/sportstyle model — a chunkier, fashion-led take on the same CloudTec platform, sold to a different buyer than the running line. Recorded because it is where On''s resale volume increasingly sits and because the same designed-void rule applies. vs the Cloud 5: the Cloudnova is visibly bulkier and is not a performance runner, so do not comp the two against each other.',
   ARRAY['CloudTec','Speedboard']::text[], '2020-present', '$150-$170', ARRAY['cloudnova','sportstyle','lifestyle','cloudtec','on running']::text[],
   'https://www.on-running.com/', 0.55, false, 'migration:00465'),
  ('onrunning', 'Cloudsurfer', ARRAY['cloudsurfer','cloud surfer','surfer','on cloudsurfer']::text[], 'Unisex', 'footwear', 'Cloud',
   'The cushioned neutral daily trainer, sitting between the Cloud 5 and the Cloudmonster. Recorded for the reason several entries in this pack exist: On''s models are named on one Cloud- prefix and are genuinely hard to separate on a flat photo, so the model must be read off the tag and never inferred from the silhouette. The Cloud- prefix identifies the BRAND well; it does not identify the model.',
   ARRAY['CloudTec','Speedboard']::text[], '2023-present', '$150-$170', ARRAY['cloudsurfer','neutral','daily trainer','cloudtec','on running']::text[],
   'https://www.on-running.com/', 0.55, false, 'migration:00465'),

  -- HOKA: the midsole is the product AND the grade.
  ('hoka', 'Bondi', ARRAY['bondi','bondi 8','hoka bondi','bondi 9']::text[], 'Unisex', 'footwear', 'Bondi',
   'HOKA''s max-cushion flagship and its highest-volume resale model — the thickest midsole in the line and the shoe the brand''s reputation is built on. THE MIDSOLE IS THE PRODUCT AND ALSO THE GRADE. Its deliberately enormous volume is the design, not swelling or delamination; but because the foam IS what the buyer wants, a COMPRESSED midsole is a TOTAL LOSS even when the upper is spotless — and it is nearly invisible in a normal photo. Look at the midsole SIDEWALL side-on: deep horizontal creasing, a flattened or collapsed section, or foam that does not spring back when squeezed means the shoe is functionally dead. Photograph the midsole from the side. vs the Clifton: the Bondi is the MAXIMUM-cushion shoe and the Clifton is the lighter everyday one — read the name, they look alike from above. Generationally numbered; read the number.',
   ARRAY['EVA foam','Meta-Rocker']::text[], '2011-present', '$165-$180', ARRAY['bondi','max cushion','midsole','hoka','meta-rocker']::text[],
   'https://www.hoka.com/', 0.70, false, 'migration:00465'),
  ('hoka', 'Clifton', ARRAY['clifton','clifton 9','hoka clifton','clifton 10']::text[], 'Unisex', 'footwear', 'Clifton',
   'THE BONDI''S TWIN AND THE PACK''S OTHER CONFUSION PAIR — the lightweight everyday trainer against the Bondi''s maximum cushion. From above the two are near-identical HOKA silhouettes; the Clifton''s stack is lower and the shoe is markedly lighter in hand, but nothing in a flat photo reliably says so. Read the model name off the shoe. Same grading rule as the Bondi: the foam is the product, so grade the MIDSOLE SIDEWALL, not the upper. Generationally numbered (Clifton 9, 10) and the buyer shops the generation.',
   ARRAY['EVA foam','Meta-Rocker']::text[], '2014-present', '$145-$160', ARRAY['clifton','lightweight','midsole','hoka','meta-rocker']::text[],
   'https://www.hoka.com/', 0.65, false, 'migration:00465'),
  ('hoka', 'Speedgoat', ARRAY['speedgoat','speed goat','hoka speedgoat','speedgoat 6']::text[], 'Unisex', 'footwear', 'Speedgoat',
   'The TRAIL shoe, named for the ultrarunner Karl Meltzer. The one HOKA genuinely separable in a photo: it has an aggressive LUGGED Vibram outsole where the road models (Bondi, Clifton) have a smooth or lightly patterned one — look at the sole. Recorded because trail wear is a different grade: worn-down LUGS are the condition axis here and they are visible, unlike the road models'' invisible foam compression. Note the rocker still applies — the shoe does not sit flat by design.',
   ARRAY['EVA foam','Vibram outsole','Meta-Rocker']::text[], '2015-present', '$155-$170', ARRAY['speedgoat','trail','vibram','lugs','hoka']::text[],
   'https://www.hoka.com/', 0.60, false, 'migration:00465'),
  ('hoka', 'Arahi', ARRAY['arahi','hoka arahi','arahi 7']::text[], 'Unisex', 'footwear', 'Arahi',
   'The STABILITY road shoe — the Clifton''s supported sibling, built with a firmer J-Frame section rather than a soft neutral midsole. Recorded as the third near-identical road silhouette: Bondi, Clifton and Arahi are all HOKA road shoes that photograph alike from above and differ in cushion and support, which a photo cannot show. The name on the shoe is the identification.',
   ARRAY['EVA foam','J-Frame','Meta-Rocker']::text[], '2017-present', '$145-$160', ARRAY['arahi','stability','j-frame','road','hoka']::text[],
   'https://www.hoka.com/', 0.55, false, 'migration:00465'),

  -- OUTDOOR VOICES: the Exercise Dress is three garments in one.
  ('outdoorvoices', 'Exercise Dress', ARRAY['exercise dress','the exercise dress','ov exercise dress','doing things dress']::text[], 'Women', 'dress', 'Exercise Dress',
   'THE Outdoor Voices product — the piece that made the brand and the bulk of its resale, comping well above the brand''s ordinary items. IT IS THREE GARMENTS IN ONE: a dress with a built-in shelf BRA and built-in SHORTS underneath, all one piece. That matters for grading: an Exercise Dress photographed inside-out or laid open shows interior layers that are the CONSTRUCTION, not a second garment, not a lining and not a defect — do not report the built-in shorts as a separate item or a manufacturing fault. Made in TechSweat, the brand''s compressive knit, so the real condition axes are pilling at the seat and stretch-sheerness, neither of which shows in a flat photo. The name is on the tag.',
   ARRAY['TechSweat']::text[], '2019-present', '$100-$120', ARRAY['exercise dress','built-in bra','built-in shorts','techsweat','outdoor voices']::text[],
   'https://www.outdoorvoices.com/', 0.65, false, 'migration:00465'),
  ('outdoorvoices', 'TechSweat Legging', ARRAY['techsweat','tech sweat','techsweat legging','7/8 legging']::text[], 'Women', 'pant', 'TechSweat',
   'The compressive performance legging and the brand''s volume bottom. TECHSWEAT IS A TAG-PRINTED FABRIC NAME, not a fit — it is the brand''s coined performance knit and it is what separates this from the CloudKnit line, which is soft brushed fleece at a different price. The two photograph similarly and comp differently, so read the fabric name off the tag. Condition: pills at the inner thigh and under the seat, and goes sheer when stretched once the elastane gives — a flat unstretched photo shows neither.',
   ARRAY['TechSweat']::text[], 'long-running', '$70-$95', ARRAY['techsweat','legging','compressive','outdoor voices']::text[],
   'https://www.outdoorvoices.com/', 0.60, false, 'migration:00465'),
  ('outdoorvoices', 'CloudKnit Sweatshirt', ARRAY['cloudknit','cloud knit','cloudknit sweatshirt','cloudknit hoodie']::text[], 'Unisex', 'sweatshirt', 'CloudKnit',
   'The soft brushed-fleece line — the TechSweat''s counterpart and the reason the fabric name has to be read rather than guessed. CloudKnit is a lounge/soft fabric where TechSweat is a compressive performance knit; both are coined names printed on the tag, both appear on similar silhouettes, and they are different products at different prices. Recorded so the pair is disambiguated from both sides.',
   ARRAY['CloudKnit']::text[], 'long-running', '$85-$110', ARRAY['cloudknit','sweatshirt','soft','lounge','outdoor voices']::text[],
   'https://www.outdoorvoices.com/', 0.55, false, 'migration:00465'),

  -- GIRLFRIEND COLLECTIVE: Compressive vs FLOAT, and the colour is the product.
  ('girlfriendcollective', 'Compressive Legging', ARRAY['compressive','compressive legging','compressive high-rise','high-rise compressive']::text[], 'Women', 'pant', 'Compressive',
   'Girlfriend Collective''s signature and volume product: the firm, high-compression legging made from RECYCLED post-consumer plastic bottles — the recycled fabric is the brand''s whole premise and the tag states it, so it belongs in the listing. vs FLOAT (the lighter, softer, buttery fabric): both are tag-printed FABRIC names on the same silhouette, they photograph identically flat, and they comp differently — read the name, do not infer it from the image. THE COLOUR NAME IS ALSO THE PRODUCT: the brand sells proprietary named colours (Moss, Plum, Ivy, Cayenne) and buyers search them, so a generic "green" loses the search a "Moss" wins. Condition: pills at the inner thigh and under the seat and goes SHEER WHEN STRETCHED once the elastane gives — a flat photo shows neither, so check and say.',
   ARRAY['Compressive','recycled polyester','RPET']::text[], '2016-present', '$68-$78', ARRAY['compressive','legging','recycled','rpet','girlfriend collective']::text[],
   'https://www.girlfriend.com/', 0.65, false, 'migration:00465'),
  ('girlfriendcollective', 'FLOAT Legging', ARRAY['float','float legging','float high-rise']::text[], 'Women', 'pant', 'FLOAT',
   'THE COMPRESSIVE''S TWIN — the lighter, softer, buttery-hand fabric against the Compressive''s firm high-compression one. Same silhouette, same colours, same brand marks, different fabric name on the tag and a different price. Nothing in a flat photo separates them. Recorded as the deliberate counterpart to the Compressive so the pair is disambiguated from both sides rather than one.',
   ARRAY['FLOAT','recycled polyester','RPET']::text[], '2021-present', '$78-$88', ARRAY['float','legging','soft','recycled','girlfriend collective']::text[],
   'https://www.girlfriend.com/', 0.60, false, 'migration:00465'),
  ('girlfriendcollective', 'Paloma Bra', ARRAY['paloma','paloma bra','the paloma']::text[], 'Women', 'top', 'Paloma',
   'The brand''s signature bra — a V-front, strappy-back sports bra and the volume top beside the Compressive legging. Recorded because it is the piece most often sold as a SET with the leggings in a matching named colour, and a matched set comps above the two pieces separately: if both pieces are present and the colour matches, say so and list it as a set. Read the colour name off the tag.',
   ARRAY['Compressive','recycled polyester','RPET']::text[], '2016-present', '$38-$48', ARRAY['paloma','bra','set','recycled','girlfriend collective']::text[],
   'https://www.girlfriend.com/', 0.55, false, 'migration:00465'),
  ('girlfriendcollective', 'Luxe Legging', ARRAY['luxe','luxe legging','luxe high-rise']::text[], 'Women', 'pant', 'Luxe',
   'The third named legging fabric — a smooth, matte, heavier hand distinct from both the Compressive and the FLOAT. Recorded to complete the set: this brand''s entire product taxonomy is FABRIC NAMES on one silhouette, so a model that reads only "black legging" has identified nothing. Three fabrics, one shape, three prices, and only the tag says which.',
   ARRAY['Luxe','recycled polyester','RPET']::text[], 'long-running', '$78-$88', ARRAY['luxe','legging','matte','recycled','girlfriend collective']::text[],
   'https://www.girlfriend.com/', 0.55, false, 'migration:00465')
on conflict (brand_key, style_name, department) do nothing;

-- ── brand_style_codes: ASICS ONLY ───────────────────────────────────────────
-- The one brand in this pack whose garment-printed identifier passes all three
-- tests (tag-printed AND regular AND BRAND-UNIQUE IN FORMAT). See the header for
-- the refusals; the two pointed ones are PUMA's six-digit style number (a bare
-- digit run — the Lee 101 rule) and Reebok's two-letters-plus-four-digits code,
-- which is tag-printed AND regular and still fails because THE FORMAT IS
-- ADIDAS'S — they shared a corporate coding system from 2006 to 2021.
insert into public.brand_style_codes
  (brand_key, decoder_kind, description, pattern, extraction_rules, examples, source_url, confidence, verified, updated_by) values
  -- ASICS's article number is DIGITS-THEN-LETTER-THEN-DIGITS (1011B491), and that
  -- shape is what earns the decoder: none of the brands it would be confused with
  -- uses it. Nike leads with letters (CW2288-111); adidas and Reebok are two
  -- letters plus four digits (GY7434); New Balance leads with a department letter
  -- (M990GL5). So the number recovers ASICS from a cut tag on its own — this
  -- pack's cut-tag case.
  --
  -- The optional trailing colour suffix (-001) is tolerated but NOT captured: it
  -- is a colour CODE, not a colour name, and `colorway` expects a name. A
  -- non-capturing group is the US-1739 rule — a bogus fieldMap target would
  -- silently write a phantom property nothing reads.
  --
  -- NOT an authenticity check: the article number identifies the MODEL, not the
  -- individual shoe, and it is printed on every box. It recovers the BRAND.
  ('asics', 'style_number',
   'ASICS tag-printed article number, on the tongue label beside the size and on the box. Eight characters: four digits, one letter, three digits (1011B491, 1201A019, 1012B420). The DIGITS-THEN-LETTER shape is what makes it brand-unique — Nike leads with letters (CW2288-111), adidas and Reebok use two letters plus four digits (GY7434), New Balance leads with a department letter (M990GL5) — so it identifies ASICS even when the brand tag itself is cut. An optional trailing colour-code suffix (-001) is tolerated but not captured, because it is a code rather than a colour name.',
   '^(?<style>\d{4}[A-Z]\d{3})(?:-\d{3})?$',
   $j${"fieldMap":{"style":"styleCode"},"transforms":{"style":"upper"},"confidence":0.6}$j$::jsonb,
   $j$[{"code":"1011B491","expected":{"styleCode":"1011B491"}},{"code":"1201A019","expected":{"styleCode":"1201A019"}},{"code":"1012b420","expected":{"styleCode":"1012B420"},"note":"Lowercase is normalized up — a tongue label is read off a photo and case is unreliable."},{"code":"1011B491-001","expected":{"styleCode":"1011B491"},"note":"The trailing colour code is tolerated but not captured: it is a code, not a colour name."},{"code":"GY7434","expected":null,"note":"The adidas/Reebok format (two letters + four digits). It must NOT recover ASICS — and it is exactly why Reebok gets no decoder of its own: the format is not brand-unique."},{"code":"CW2288-111","expected":null,"note":"A Nike style code (letters first) must NOT recover ASICS."},{"code":"380190","expected":null,"note":"A PUMA six-digit style number is a bare digit run and must recover nothing (the Lee 101 rule)."},{"code":"1130","expected":null,"note":"The GEL-1130 model number is ASICS's own, and it is STILL a bare digit run — a model name, not a code. It must NOT recover a brand on its own (the Lee 101 rule), which is why only the 8-character article number is decoded."},{"code":"M990GL5","expected":null,"note":"A New Balance model number (department letter first) must NOT recover ASICS."}]$j$::jsonb,
   'https://www.asics.com/', 0.60, false, 'migration:00465')
on conflict (brand_key, decoder_kind) do nothing;

-- ── brand_colorways ─────────────────────────────────────────────────────────
-- Seeded ONLY where the brand's colour name is a STABLE, brand-DEFINING term
-- rather than a season's fancy — the 00464 rule.
--
-- That is essentially just GIRLFRIEND COLLECTIVE, and there it is unusually
-- load-bearing: the brand sells the same few silhouettes in a rotating palette of
-- proprietary NAMED colours, so the colour name IS the product variant and it is
-- what buyers search. A retired colour is genuinely sought.
--
-- Deliberately NOT seeded: the five athletic brands' colourways are per-model and
-- per-season (the Nike problem — a Suede comes in a hundred colours a year and
-- naming them is a catalogue, not knowledge); On and HOKA name colours as
-- seasonal pairs (Eclipse/Black); Outdoor Voices' palette rotates seasonally.
-- Champion's one entry is its long-running house grey, which is stable and is the
-- colour most vintage Champion actually is.
