   $json$[{"size":"US W6 = UK 3.5 = EU 36.5","measurements":{"footLength":"8.9"}},{"size":"US W7 = UK 4.5 = EU 37.5","measurements":{"footLength":"9.25"}},{"size":"US W8 = UK 5.5 = EU 39","measurements":{"footLength":"9.5"}},{"size":"US W9 = UK 6.5 = EU 40","measurements":{"footLength":"9.9"}},{"size":"US W10 = UK 7.5 = EU 41.5","measurements":{"footLength":"10.2"}},{"size":"US W11 = UK 8.5 = EU 42.5","measurements":{"footLength":"10.5"}}]$json$::jsonb,
