on conflict (brand_key, department, garment) do update set
  rows = excluded.rows, note = excluded.note, category_match = excluded.category_match,
  source_url = excluded.source_url, confidence = excluded.confidence,
  brand_match = excluded.brand_match, updated_by = excluded.updated_by;

-- NOTE — no shared-chart narrowing is needed here (contrast 00453, which had to
-- narrow the shared outdoor row). Verified against the shipped table: none of the
-- nine brands is claimed by an existing multi-brand chart. The 00459 footwear
-- brands each carry their own rows and none of their brand_match tokens reaches
-- these nine; the generic alpha/pants fallbacks have an EMPTY brand_match, so
-- they are only selected when no brand chart matched.
--
-- THE brand_match TOKENS THAT ARE DELIBERATELY ABSENT, and why:
--   * "on" — NEVER. findSizingCharts' brandTextMatches is LEADING-word-boundary
--     only, and "on" starts the word "Onitsuka", so a bare "on" token would hand
--     an Onitsuka Tiger On Running's charts. The canonical "On Running" is what
--     the resolver passes anyway, so the chart is reached without it.
--   * "ov" / "girlfriend" — NEVER. Both are alias KEYS only (an exact whole-field
--     lookup, which cannot false-fire); a 2-letter or ordinary-word token in
--     brand_match is the "ag"-hands-Patagonia-AG's-charts bug (US-1735).
--   * "outdoor" / "cloud" / "one one" — NEVER. Ordinary category words.
-- Both directions are verified in activewear-content_test.ts.

-- US-1108 self-record footer.
insert into public.applied_migrations (version) values ('00465') on conflict do nothing;
